// Package Manager feature module. Validated runtime configuration.
namespace ClearGameEngine.RootFeatures;
public sealed class PackageManagerFeature:FeatureModuleBase{public const string FeatureId="package-manager";public PackageManagerFeature():base(FeatureId,"Package Manager",new FeatureSetting("budget","Package Manager budget",704,1,100000),new FeatureSetting("quality","Quality level",2,0,4)){} public int Budget{get=>TryGet("budget",out var v)?(int)v:512;set=>TrySet("budget",value);} public int Quality{get=>TryGet("quality",out var v)?(int)v:2;set=>TrySet("quality",value);} public bool IsConfigured=>Validate(out _);}
